import numpy as np, mujoco
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
s=Session(); m=s.model; d=s.data
site=m.site('robot_pinch_site').id; ids=np.array([m.joint(f'robot_joint_{i}').id for i in range(1,8)]); adr=m.jnt_qposadr[ids]
